<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_login();$user=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$visibility=($_POST['visibility']??'')==='private'?'private':'unlisted';$stmt=$pdo->prepare('UPDATE twibbons SET visibility=? WHERE id=? AND owner_id=?');$stmt->execute([$visibility,$id,$user['id']]);flash('success',$visibility==='private'?'Template sekarang hanya dapat diakses oleh Anda.':'Template sekarang dapat diakses oleh siapa pun yang memiliki tautan.');header('Location: privacy');exit;}
$flash=pull_flash();$stmt=$pdo->prepare("SELECT * FROM twibbons WHERE owner_id=? ORDER BY created_at DESC");$stmt->execute([$user['id']]);$items=$stmt->fetchAll();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Privasi Template — Bingkaiin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">B</span>Bingkaiin</a><nav class="nav-links"><a href="./">Beranda</a><a href="dashboard">Dashboard</a><a class="active" href="privacy">Privasi</a><a href="logout">Keluar</a></nav></div></header><main class="container"><div class="page-head"><span class="eyebrow">Kontrol akses</span><h1 class="page-title" style="margin-top:12px">Privasi template</h1><p class="subtitle">Tentukan siapa yang dapat membuka setiap template milikmu.</p></div><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif?><div class="grid"><?php foreach($items as $item):?><article class="card template-card"><div class="thumb"><img src="uploads/<?=e(basename($item['template_image']))?>" alt=""></div><div class="card-body"><span class="visibility <?=$item['visibility']==='private'?'visibility-private':'visibility-unlisted'?>"><?=$item['visibility']==='private'?'Pribadi':'Via tautan'?></span><h3 style="margin-top:12px"><?=e($item['title'])?></h3><p><?=$item['visibility']==='private'?'Hanya Anda dan admin yang dapat membuka template ini.':'Siapa pun yang memiliki URL dapat menggunakan template ini.'?></p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><input type="hidden" name="visibility" value="<?=$item['visibility']==='private'?'unlisted':'private'?>"><button class="btn <?=$item['visibility']==='private'?'btn-primary':'btn-secondary'?>" style="width:100%"><?=$item['visibility']==='private'?'Ubah menjadi via tautan':'Jadikan pribadi'?></button></form></div></article><?php endforeach?></div><?php if(!$items):?><div class="empty">Belum ada template untuk diatur. <a href="dashboard">Buat sekarang</a>.</div><?php endif?></main><footer class="footer">Bingkaiin · Produk digital dari Apins Digital</footer></body></html>
